import webpush from 'web-push';
import { getDb } from '@airways/database';
import { pushSubscriptions, notificationWatermark, flightStatusHistory } from '@airways/database/schema';
import { eq, gt, inArray, sql } from 'drizzle-orm';

webpush.setVapidDetails(
  process.env.VAPID_SUBJECT!,
  process.env.VAPID_PUBLIC_KEY!,
  process.env.VAPID_PRIVATE_KEY!,
);

export async function dispatch(): Promise<void> {
  const db = getDb();

  // 1. Get or initialise the watermark row
  const watermarkRows = await db.select().from(notificationWatermark).limit(1);
  let watermarkId: number;
  let watermarkRowId: number;

  if (watermarkRows.length === 0) {
    // First run: initialise to the current max id so we don't replay history
    const maxRow = await db
      .select({ maxId: sql<number>`coalesce(max(id), 0)` })
      .from(flightStatusHistory);
    const initialId = maxRow[0]?.maxId ?? 0;

    const inserted = await db
      .insert(notificationWatermark)
      .values({ lastProcessedId: initialId })
      .returning();
    watermarkId = inserted[0].lastProcessedId;
    watermarkRowId = inserted[0].id;
    console.log(`[Notify] Initialised watermark to ${watermarkId}`);
    return;
  } else {
    watermarkId = watermarkRows[0].lastProcessedId;
    watermarkRowId = watermarkRows[0].id;
  }

  // 2. Fetch up to 50 new status history rows
  const newRows = await db
    .select({
      id: flightStatusHistory.id,
      flightId: flightStatusHistory.flightId,
      flightCode: flightStatusHistory.flightCode,
      flightDate: flightStatusHistory.flightDate,
      statusMessage: flightStatusHistory.statusMessage,
    })
    .from(flightStatusHistory)
    .where(gt(flightStatusHistory.id, watermarkId))
    .orderBy(flightStatusHistory.id)
    .limit(50);

  if (newRows.length === 0) return;

  const maxProcessedId = newRows[newRows.length - 1].id;

  // 3. Group by flightId, keep the latest status per flight
  const latestByFlight = new Map<
    number,
    { flightId: number; flightCode: string; flightDate: string; statusMessage: string }
  >();
  for (const row of newRows) {
    if (row.flightId == null) continue;
    latestByFlight.set(row.flightId, {
      flightId: row.flightId,
      flightCode: row.flightCode,
      flightDate: row.flightDate,
      statusMessage: row.statusMessage,
    });
  }

  if (latestByFlight.size === 0) {
    await advanceWatermark(db, watermarkRowId, maxProcessedId);
    return;
  }

  // 4. Look up subscriptions for affected flights
  const flightIds = Array.from(latestByFlight.keys());
  const subs = await db
    .select()
    .from(pushSubscriptions)
    .where(inArray(pushSubscriptions.flightId, flightIds));

  // 5. Send notifications, collect endpoints to delete on 410/404
  const endpointsToDelete: string[] = [];

  await Promise.allSettled(
    subs.map(async (sub) => {
      const flightInfo = latestByFlight.get(sub.flightId);
      if (!flightInfo) return;

      const payload = JSON.stringify({
        title: `${flightInfo.flightCode} — Status Update`,
        body: flightInfo.statusMessage,
        url: `/flights/${sub.flightId}`,
        flightId: sub.flightId,
      });

      try {
        await webpush.sendNotification(
          sub.subscription as webpush.PushSubscription,
          payload,
        );
        // Update lastNotifiedAt
        await db
          .update(pushSubscriptions)
          .set({ lastNotifiedAt: new Date() })
          .where(eq(pushSubscriptions.id, sub.id));
      } catch (err: unknown) {
        const statusCode = (err as { statusCode?: number })?.statusCode;
        if (statusCode === 410 || statusCode === 404) {
          // Subscription is gone — remove all flights for this endpoint
          endpointsToDelete.push(sub.endpoint);
        } else {
          console.error(`[Notify] Failed to send to endpoint (flight ${sub.flightId}):`, (err as Error).message);
        }
      }
    }),
  );

  // 6. Clean up dead subscriptions
  if (endpointsToDelete.length > 0) {
    const unique = [...new Set(endpointsToDelete)];
    await db
      .delete(pushSubscriptions)
      .where(inArray(pushSubscriptions.endpoint, unique));
    console.log(`[Notify] Removed ${unique.length} expired endpoint(s)`);
  }

  // 7. Advance watermark
  await advanceWatermark(db, watermarkRowId, maxProcessedId);
  console.log(`[Notify] Processed up to id=${maxProcessedId}, sent to ${subs.length} subscription(s)`);
}

async function advanceWatermark(
  db: ReturnType<typeof getDb>,
  rowId: number,
  newId: number,
): Promise<void> {
  await db
    .update(notificationWatermark)
    .set({ lastProcessedId: newId, updatedAt: new Date() })
    .where(eq(notificationWatermark.id, rowId));
}

import { loadEnv } from '@airways/common';
loadEnv({ serviceName: 'Notify', startDir: __dirname, logPath: true });

import { dispatch } from './dispatcher';
import { sendAlert } from '@airways/telegram';

async function main() {
  const intervalMs = parseInt(process.env.NOTIFY_POLL_INTERVAL_MS ?? '15000', 10);
  console.log('[Notify] Notification service starting...');
  console.log(`[Notify] Poll interval: ${intervalMs}ms`);

  if (!process.env.VAPID_PUBLIC_KEY || !process.env.VAPID_PRIVATE_KEY || !process.env.VAPID_SUBJECT) {
    console.error('[Notify] VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, and VAPID_SUBJECT must all be set');
    await sendAlert('notification-service', 'critical', 'VAPID keys not configured — push notifications will not work');
    process.exit(1);
  }

  async function runPoll() {
    try {
      await dispatch();
    } catch (err) {
      console.error('[Notify] Dispatch failed:', err);
      sendAlert('notification-service', 'warning', 'Dispatch failed', err).catch(() => {});
    }
    setTimeout(runPoll, intervalMs);
  }

  runPoll();
}

main().catch(err => {
  console.error('[Notify] Fatal error:', err);
  sendAlert('notification-service', 'critical', 'Fatal error', err).finally(() => process.exit(1));
});

import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { pushSubscriptions } from '$lib/server/db';
import { eq, and } from 'drizzle-orm';

export const POST: RequestHandler = async ({ request }) => {
  let body: { subscription: PushSubscription; flightId: number; flightCode: string; flightDate: string };
  try {
    body = await request.json();
  } catch {
    throw error(400, 'Invalid JSON');
  }

  const { subscription, flightId, flightCode, flightDate } = body;
  if (!subscription?.endpoint || !flightId || !flightCode || !flightDate) {
    throw error(400, 'Missing required fields');
  }

  const db = getDb();
  await db
    .insert(pushSubscriptions)
    .values({
      endpoint: subscription.endpoint,
      subscription: subscription as unknown as Record<string, unknown>,
      flightId,
      flightCode,
      flightDate,
    })
    .onConflictDoUpdate({
      target: [pushSubscriptions.endpoint, pushSubscriptions.flightId],
      set: {
        subscription: subscription as unknown as Record<string, unknown>,
        flightCode,
        flightDate,
      },
    });

  return json({ ok: true });
};

export const DELETE: RequestHandler = async ({ request }) => {
  let body: { endpoint: string; flightId: number };
  try {
    body = await request.json();
  } catch {
    throw error(400, 'Invalid JSON');
  }

  const { endpoint, flightId } = body;
  if (!endpoint || !flightId) {
    throw error(400, 'Missing required fields');
  }

  const db = getDb();
  await db
    .delete(pushSubscriptions)
    .where(and(eq(pushSubscriptions.endpoint, endpoint), eq(pushSubscriptions.flightId, flightId)));

  return json({ ok: true });
};

import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { pushSubscriptions } from '$lib/server/db';
import { eq, and } from 'drizzle-orm';

export const GET: RequestHandler = async ({ params, url }) => {
  const flightId = parseInt(params.flightId, 10);
  if (isNaN(flightId)) throw error(400, 'Invalid flightId');

  const endpoint = url.searchParams.get('endpoint');
  if (!endpoint) throw error(400, 'Missing endpoint');

  const db = getDb();
  const rows = await db
    .select({ id: pushSubscriptions.id })
    .from(pushSubscriptions)
    .where(and(eq(pushSubscriptions.flightId, flightId), eq(pushSubscriptions.endpoint, endpoint)))
    .limit(1);

  return json({ subscribed: rows.length > 0 });
};

import { env } from '$env/dynamic/private';
import { json } from '@sveltejs/kit';
import type { Handle, HandleServerError } from '@sveltejs/kit';
import { validateDebugToken } from '$lib/server/debug-helpers';

export const handle: Handle = async ({ event, resolve }) => {
  // Debug API auth — gate /api/debug/* behind Bearer token
  if (event.url.pathname.startsWith('/api/debug/')) {
    const auth = event.request.headers.get('authorization');
    if (!validateDebugToken(auth, env.DEBUG_API_TOKEN)) {
      return json({ error: 'Unauthorized' }, { status: 401 });
    }
  }

  const response = await resolve(event);
  if (
    event.request.method === 'GET' &&
    (response.headers.get('content-type') ?? '').includes('text/html')
  ) {
    // If the request carries the recently-viewed cookie the response is personalised,
    // so it must not be stored in a shared cache (CDN). Non-cookied visitors (first-time
    // or cleared) are safe to cache publicly.
    const personalized = event.request.headers.get('cookie')?.includes('rv=') ?? false;
    response.headers.set(
      'Cache-Control',
      personalized
        ? 'private, max-age=0'
        : 'public, max-age=0, s-maxage=30, stale-while-revalidate=60',
    );
  }
  return response;
};

export const handleError: HandleServerError = ({ error, event, status }) => {
  // Log server-side errors with context (avoids leaking stack traces to the client)
  const message = error instanceof Error ? error.message : 'Unknown error';
  console.error(`[server error] ${status} on ${event.url.pathname}: ${message}`);

  // Return a safe, generic message to the client
  return {
    message: status === 404 ? 'Not found' : 'An unexpected error occurred',
  };
